INSERT INTO lesson_plan_template_field (id, lesson_plan_template_id, title, body, visibility, sequence, created_at, updated_at, deleted_at) VALUES (38, 6, 'Typical Duration', '<p>Add the duration that you anticipate this plan will require.</p>', 'staff', 1, '2023-03-28 17:45:21.0', '2023-03-28 17:45:21.0', null);
INSERT INTO lesson_plan_template_field (id, lesson_plan_template_id, title, body, visibility, sequence, created_at, updated_at, deleted_at) VALUES (39, 6, 'Nature of Inquiry', '<p>Add a statement that frames the inquiry taking place.</p>', 'student', 2, '2023-03-28 17:45:21.0', '2023-03-28 17:45:21.0', null);
INSERT INTO lesson_plan_template_field (id, lesson_plan_template_id, title, body, visibility, sequence, created_at, updated_at, deleted_at) VALUES (40, 6, 'Factual Inquiry Questions', '<p>Where applicable, add an inquiry question that has a right or wrong answer. Typically these require a student to know who, what, when, where.</p>', 'student', 3, '2023-03-28 17:45:21.0', '2023-03-28 17:45:21.0', null);
INSERT INTO lesson_plan_template_field (id, lesson_plan_template_id, title, body, visibility, sequence, created_at, updated_at, deleted_at) VALUES (41, 6, 'Conceptual Inquiry Questions', '<p>Where applicable, add an inquiry question that requires understanding or transferable knowledge. Typically these questions require a student to know how.</p>', 'student', 4, '2023-03-28 17:45:21.0', '2023-03-28 17:45:21.0', null);
INSERT INTO lesson_plan_template_field (id, lesson_plan_template_id, title, body, visibility, sequence, created_at, updated_at, deleted_at) VALUES (42, 6, 'Debatable Inquiry Questions', '<p>Where applicable, add an inquiry question that requires consideration from multiple perspectives. Typically these questions require a student to form an opinion.</p>', 'student', 5, '2023-03-28 17:45:21.0', '2023-03-28 17:45:21.0', null);
INSERT INTO lesson_plan_template_field (id, lesson_plan_template_id, title, body, visibility, sequence, created_at, updated_at, deleted_at) VALUES (43, 6, 'Key Learning Behaviours', '<p>Add information about the learning behaviours that students can demonstrate and practise through this lesson to enable them to access learning and interact with others productively in the community.</p>', 'student', 6, '2023-03-28 17:45:21.0', '2023-03-28 17:45:21.0', null);
INSERT INTO lesson_plan_template_field (id, lesson_plan_template_id, title, body, visibility, sequence, created_at, updated_at, deleted_at) VALUES (44, 6, 'Differentiation Strategies', '<p>Add strategies that will be used to stretch and challenge high achieving students.</p><p>Add strategies that will be used to support low achieving students.<br>&nbsp;</p>', 'staff', 7, '2023-03-28 17:45:21.0', '2023-03-28 17:45:21.0', null);
INSERT INTO lesson_plan_template_field (id, lesson_plan_template_id, title, body, visibility, sequence, created_at, updated_at, deleted_at) VALUES (45, 6, 'Teacher Notes', '', 'staff', 8, '2023-03-28 17:45:21.0', '2023-03-28 17:45:21.0', null);
